package com.keplerslicer.app;
import android.content.Context;
import org.json.*;
import java.io.File;
public final class CloudMirrorTest {
    private static int checks;
    private static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
    private static CloudProfileSync.Pull pull(String body)throws Exception{return new CloudProfileSync((method,path,json)->new CloudProfileSync.Response(200,body)).pull(0);}
    public static void main(String[] args)throws Exception{
        Context context=new Context(new File(args[0]),new File(args[0],"assets"));CloudProfileStore store=new CloudProfileStore(context,"A");check(!store.hasSnapshot(),"An empty cache is not a known empty server snapshot");store.apply(new CloudProfileSync((m,p,b)->new CloudProfileSync.Response(304,"")).pull(0));check(!store.hasSnapshot(),"304 cannot establish an initial authoritative mirror");store.apply(pull("{\"next_cursor\":0,\"upserts\":[],\"deletes\":[]}"));check(store.hasSnapshot(),"A successful full empty snapshot is authoritative even with cursor zero");
        String id="11111111-1111-4111-8111-111111111111",other="22222222-2222-4222-8222-222222222222";JSONObject first=new JSONObject().put("id",id).put("updated_time",1).put("content",new JSONObject().put("name","A").put("value",new JSONArray("[null,true]")));JSONObject second=new JSONObject().put("id",other).put("updated_time",1).put("content",new JSONObject().put("name","B"));store.apply(pull(new JSONObject().put("next_cursor",10).put("upserts",new JSONArray().put(first).put(second)).put("deletes",new JSONArray()).toString()));check(store.cursor()==10&&store.profiles().length()==2,"Full profiles and cursor commit together");store.removeAcknowledged(id);check(store.profiles().length()==1&&store.profiles().getJSONObject(0).getString("id").equals(other),"Delete acknowledgment removes only the specified mirror row");check(store.cursor()==10,"Delete acknowledgment does not invent a newer server cursor");store.resetCursor();check(store.cursor()==0&&store.profiles().length()==1&&store.hasSnapshot(),"Cursor reset retains known profile data for the next full pull");check(!new CloudProfileStore(context,"B").hasSnapshot(),"Accounts have separate mirror files");store.edit(other,new JSONObject().put("name","B local"));second.put("updated_time",2);store.apply(pull(new JSONObject().put("next_cursor",11).put("upserts",new JSONArray().put(second)).put("deletes",new JSONArray()).toString()));check(store.conflictCount()==1,"Dirty local mirror edit is preserved as a conflict");check(store.profiles().getJSONObject(0).getJSONObject("content").getString("name").equals("B local"),"Server update cannot erase dirty mirror source");
        CloudProfileStore race=new CloudProfileStore(context,"stale-race");JSONObject early=new JSONObject().put("id",id).put("updated_time",100).put("content",new JSONObject().put("name","T1"));race.apply(pull(new JSONObject().put("next_cursor",100).put("upserts",new JSONArray().put(early)).put("deletes",new JSONArray()).toString()));race.upsertAcknowledged(id,"T2",new JSONObject().put("name","T2"),200);race.apply(pull(new JSONObject().put("next_cursor",100).put("upserts",new JSONArray().put(early)).put("deletes",new JSONArray()).toString()));check(race.profiles().getJSONObject(0).getJSONObject("content").getString("name").equals("T2"),"GET T1 arriving after acknowledged push T2 cannot roll back a clean mirror");race.apply(pull("{\"next_cursor\":100,\"upserts\":[],\"deletes\":[\"11111111-1111-4111-8111-111111111111\"]}"));check(race.profiles().length()==1,"Stale explicit deletion or full-snapshot omission cannot erase newer upload T2");race.apply(pull("{\"next_cursor\":300,\"upserts\":[],\"deletes\":[]}"));check(race.profiles().length()==0,"Newer authoritative deletion still applies");early.put("updated_time",200);race.apply(pull(new JSONObject().put("next_cursor",400).put("upserts",new JSONArray().put(early)).put("deletes",new JSONArray()).toString()));check(race.profiles().length()==0,"Versioned deletion prevents older upsert resurrection even with a newer batch cursor");early.put("updated_time",350).put("content",new JSONObject().put("name","Recreated"));race.apply(pull(new JSONObject().put("next_cursor",450).put("upserts",new JSONArray().put(early)).put("deletes",new JSONArray()).toString()));check(race.profiles().length()==1,"A strictly newer server recreation is accepted");race.edit(id,new JSONObject().put("name","Local dirty"));early.put("updated_time",360).put("content",new JSONObject().put("name","Server360"));race.apply(pull(new JSONObject().put("next_cursor",460).put("upserts",new JSONArray().put(early)).put("deletes",new JSONArray()).toString()));early.put("updated_time",355).put("content",new JSONObject().put("name","Stale355"));race.apply(pull(new JSONObject().put("next_cursor",470).put("upserts",new JSONArray().put(early)).put("deletes",new JSONArray()).toString()));check(race.conflicts().getJSONObject(id).getJSONObject("server").getJSONObject("content").getString("name").equals("Server360"),"An older upsert cannot regress the preserved server conflict revision");try{race.apply(pull("{\"next_cursor\":469,\"upserts\":[],\"deletes\":[]}"));throw new AssertionError("Old cursor must fail");}catch(java.io.IOException expected){checks++;}check(race.conflictCount()==1,"Rejecting an old batch cursor retains conflict evidence");race.apply(pull("{\"next_cursor\":480,\"upserts\":[],\"deletes\":[]}"));check(race.conflicts().getJSONObject(id).optBoolean("deleted"),"Newer server deletion becomes a reviewed conflict for dirty local data");early.put("updated_time",470);race.apply(pull(new JSONObject().put("next_cursor",490).put("upserts",new JSONArray().put(early)).put("deletes",new JSONArray()).toString()));check(race.conflicts().getJSONObject(id).optBoolean("deleted"),"Older server content cannot replace a newer deleted conflict");try{race.markPushed(id,new JSONObject().put("name","Local dirty").toString(),400);throw new AssertionError("Old push ack must fail");}catch(java.io.IOException expected){checks++;}check(race.profiles().getJSONObject(0).getJSONObject("content").getString("name").equals("Local dirty"),"Rejected stale acknowledgment retains current local source");
        race.recordConflict(id,new JSONObject().put("server_profile",new JSONObject().put("updated_time",400)));check(race.conflicts().getJSONObject(id).optBoolean("deleted"),"An older 409 response cannot replace newer deletion conflict evidence");race.recordConflict(id,new JSONObject().put("server_profile",new JSONObject().put("updated_time",500)));try{race.serverProfiles();throw new AssertionError("Incomplete newer conflict response requires refresh");}catch(java.io.IOException expected){checks++;}early.put("updated_time",499);race.apply(pull(new JSONObject().put("next_cursor",501).put("upserts",new JSONArray().put(early)).put("deletes",new JSONArray()).toString()));check(race.conflicts().getJSONObject(id).optLong("response_revision")==500,"An older snapshot cannot replace a newer incomplete conflict revision");
        System.out.println("Cloud mirror: "+checks+" checks passed; Android AtomicFile boundary double, no network");
    }
}
